"""Algorithm C — Interaction-Aware Multilingual Budget Table (log-space, quantized)."""

from __future__ import annotations

import math
from typing import Dict, Iterable, List, Tuple


class InteractionBudgetTable:
    """A budget table that is additive in log-space rather than in the budget itself.

    No table of the separable form budget(lam, C) = f(C) + g(lam) can exist for a
    genuinely fragmenting language, so the table stores the three coefficients of the
    affine log-law

        log budget(lam, C) = c0 + theta * log(lam) + theta * log(C),   theta = b / a,

    and evaluates by exponentiating.  Lookup and storage are O(1) per language.
    """

    def __init__(self, c0: float, theta: float, grid: float = 1.0) -> None:
        if grid <= 0.0:
            raise ValueError("grid must be positive")
        self.c0 = c0
        self.theta = theta
        self.grid = grid
        self.ratios: Dict[str, float] = {}

    def register_language(self, name: str, fragmentation_ratio: float) -> None:
        if fragmentation_ratio <= 0.0:
            raise ValueError("fragmentation ratio must be positive")
        self.ratios[name] = fragmentation_ratio

    def budget(self, language: str, context: float) -> float:
        """Exact real key budget for `language` at context length `context`."""
        lam = self.ratios[language]
        return math.exp(self.c0 + self.theta * math.log(lam)
                        + self.theta * math.log(context))

    def blocks(self, language: str, context: float) -> int:
        """Allocation blocks required; quantization cannot absorb the amplification."""
        return math.ceil(self.budget(language, context) / self.grid)

    def tax(self, language: str, context: float, reference: str) -> float:
        """Extra keys `language` demands over `reference` at this context."""
        return self.budget(language, context) - self.budget(reference, context)

    def render(self, languages: Iterable[str], contexts: Iterable[float],
               reference: str) -> List[Tuple[str, float, float, float, int]]:
        """Rows of (language, context, budget, tax vs reference, blocks)."""
        out: List[Tuple[str, float, float, float, int]] = []
        for lang in languages:
            for ctx in contexts:
                out.append((lang, ctx, self.budget(lang, ctx),
                            self.tax(lang, ctx, reference), self.blocks(lang, ctx)))
        return out


if __name__ == "__main__":
    table = InteractionBudgetTable(c0=math.log(2.0), theta=1.0, grid=4.0)
    table.register_language("English", 1.00)
    table.register_language("French", 1.15)
    table.register_language("German", 1.30)

    print(f"{'lang':8s} {'ctx':>7s} {'budget':>10s} {'tax':>9s} {'blocks':>7s}")
    for row in table.render(["English", "French", "German"],
                            [512.0, 1024.0, 2048.0, 4096.0], reference="English"):
        lang, ctx, bud, tx, blk = row
        print(f"{lang:8s} {ctx:7.0f} {bud:10.2f} {tx:9.2f} {blk:7d}")
    print()
    print("the tax column quadruples with every quadrupling of the context: "
          "the interaction term is not optional.")
